const test=require('node:test');const assert=require('node:assert/strict');const {createApp}=require('../server/app');const {openStore}=require('../server/store');const commerce=require('../ai/commerce/rideplate-commerce-intelligence-agent');const {createOrderAuthority}=require('../server/commerce/orders');const {createPaymentAuthority,createLedgerAuthority,createProviderBoundary,createMpesaAdapter,createPaymentIntentAuthority,createSettlementAuthority,createPaymentSideEffectOutbox,createSideEffectRuntime,createPaymentInitiationRuntime,createProviderCallbackRuntime}=require('../server/payments');const {createInventoryAuthority}=require('../server/commerce/inventory');const {createPricingAuthority}=require('../server/commerce/pricing');const {createCommerceCancellationCoordinator}=require('../server/commerce/recovery');
test('commerce economics optimizes whole transaction, not menu price alone',async()=>{const r=await commerce.execute({input:{options:[{merchantId:'A',authoritativeTotal:1250,basketCompleteness:1,merchantReliability:.9,preparationMinutes:20,distanceKm:5,fulfillmentAvailability:.8,inventoryConfirmed:true,priceConfirmed:true,basket:['meal']},{merchantId:'B',authoritativeTotal:1150,basketCompleteness:1,merchantReliability:.9,preparationMinutes:20,distanceKm:5,fulfillmentAvailability:.8,inventoryConfirmed:true,priceConfirmed:true,basket:['meal']}]}});assert.equal(r.status,'SUCCESS');assert.equal(r.data.merchant_id,'B');assert.equal(r.data.authority,'RECOMMENDATION_ONLY');});
test('unconfirmed inventory or price is never presented as feasible',async()=>{const r=await commerce.execute({input:{options:[{merchantId:'A',authoritativeTotal:500,basketCompleteness:1,inventoryConfirmed:false,priceConfirmed:true}]}});assert.equal(r.status,'UNAVAILABLE');assert.equal(r.error.code,'NO_CONFIRMED_COMMERCE_PLAN');});
test('multi-store candidates can be represented as an authoritative plan option',async()=>{const r=await commerce.execute({input:{options:[{merchantId:'PLAN:A+B',authoritativeTotal:1400,basketCompleteness:1,merchantReliability:.8,preparationMinutes:30,distanceKm:7,fulfillmentAvailability:.9,inventoryConfirmed:true,priceConfirmed:true,basket:[{merchantId:'A',item:'food'},{merchantId:'B',item:'groceries'}]}]}});assert.equal(r.data.basket.length,2);});
test('order creation is idempotent',()=>{const db=openStore(':memory:');const a=createOrderAuthority({db});const x={customerId:'c1',merchantId:'m1',basket:[{sku:'x',qty:1}],total:100,currency:'KES',idempotencyKey:'order-1'};const one=a.create(x),two=a.create(x);assert.equal(one.id,two.id);assert.equal(two.duplicate,true);db.close();});
test('authoritative commerce facts require authority bindings',()=>{const db=openStore(':memory:');const a=createOrderAuthority({db});const o=a.create({customerId:'c1',merchantId:'m1',basket:[{sku:'x',qty:1}],total:100,idempotencyKey:'order-2'});a.transition({orderId:o.id,to:'VALIDATED'});assert.throws(()=>a.transition({orderId:o.id,to:'PRICE_CONFIRMED'}),e=>e.code==='AUTHORITATIVE_BINDING_REQUIRED');assert.throws(()=>a.transition({orderId:o.id,to:'PRICE_CONFIRMED',evidenceRef:'catalog:v1:sku-x'}),e=>e.code==='AUTHORITATIVE_BINDING_REQUIRED');db.close();});
test('invalid authoritative total is never feasible',async()=>{const r=await commerce.execute({input:{options:[{merchantId:'A',authoritativeTotal:'not-a-price',basketCompleteness:1,merchantReliability:.8,preparationMinutes:10,distanceKm:2,fulfillmentAvailability:.9,inventoryConfirmed:true,priceConfirmed:true,basket:['meal']}]}});assert.equal(r.status,'UNAVAILABLE');assert.equal(r.error.code,'NO_CONFIRMED_COMMERCE_PLAN');});
test('commerce ranking clamps caller supplied normalized factors',async()=>{const base={basketCompleteness:1,preparationMinutes:10,distanceKm:2,inventoryConfirmed:true,priceConfirmed:true,basket:['meal']};const r=await commerce.execute({input:{options:[{...base,merchantId:'A',authoritativeTotal:1000,merchantReliability:99,fulfillmentAvailability:99},{...base,merchantId:'B',authoritativeTotal:900,merchantReliability:1,fulfillmentAvailability:1}]}});assert.equal(r.status,'SUCCESS');assert.equal(r.data.merchant_id,'B');});
test('order idempotency key cannot be replayed with a different payload',()=>{const db=openStore(':memory:');const a=createOrderAuthority({db});a.create({customerId:'c1',merchantId:'m1',basket:[{sku:'x',qty:1}],total:100,idempotencyKey:'order-mismatch'});assert.throws(()=>a.create({customerId:'c1',merchantId:'m1',basket:[{sku:'x',qty:2}],total:200,idempotencyKey:'order-mismatch'}),e=>e.code==='IDEMPOTENCY_PAYLOAD_MISMATCH');db.close();});
test('generic commerce evidence cannot fabricate external authority facts',()=>{const db=openStore(':memory:');const a=createOrderAuthority({db});const o=a.create({customerId:'c1',merchantId:'m1',basket:[{sku:'x',qty:1}],total:100,idempotencyKey:'order-bind'});a.transition({orderId:o.id,to:'VALIDATED'});db.prepare("UPDATE commerce_orders SET status='PRICE_CONFIRMED' WHERE id=?").run(o.id);a.transition({orderId:o.id,to:'PAYMENT_PENDING'});assert.throws(()=>a.transition({orderId:o.id,to:'PAYMENT_CONFIRMED',evidenceRef:'payment:claimed'}),e=>e.code==='AUTHORITATIVE_BINDING_REQUIRED');db.close();});

function makePayableCommerce({db,orders,order,merchantId='m1',sku='x',unitPrice,qty=1}){const inventory=createInventoryAuthority({db}),pricing=createPricingAuthority({db}),merchant={id:merchantId,role:'agent'};inventory.setStock({merchantId,sku,quantity:Math.max(qty,5),unitPrice,currency:'KES',actor:merchant});pricing.confirm({orderId:order.id,actor:merchant});orders.transition({orderId:order.id,to:'PAYMENT_PENDING'});return {inventory,pricing,merchant};}
test('commerce payment confirmation is bound to Payment Authority state',()=>{const db=openStore(':memory:');db.prepare("INSERT INTO users VALUES('admin','a@x','Admin','x','admin',1)").run();const orders=createOrderAuthority({db}),payments=createPaymentAuthority({db});const o=orders.create({customerId:'c1',merchantId:'m1',basket:[{sku:'x',qty:1}],total:100,currency:'KES',idempotencyKey:'pay-bind'});orders.transition({orderId:o.id,to:'VALIDATED'});makePayableCommerce({db,orders,order:o,unitPrice:100});const p=payments.createCommercePayment({orderId:o.id});assert.throws(()=>orders.confirmPayment({orderId:o.id}),e=>e.code==='COMMERCE_PAYMENT_NOT_CONFIRMED');payments.verifyCommerceManual({paymentId:p.id,reference:'PAYREF01',amount:100,actor:{id:'admin',role:'admin'}});assert.equal(orders.confirmPayment({orderId:o.id}).status,'PAYMENT_CONFIRMED');db.close();});
test('commerce custody facts are bound to linked Logistics Authority state',()=>{const db=openStore(':memory:');const orders=createOrderAuthority({db});const o=orders.create({customerId:'c1',merchantId:'m1',basket:[{sku:'x',qty:1}],total:100,idempotencyKey:'ship-bind'});db.prepare("INSERT INTO logistics_shipments(id,customer_id,shipment_class,weight_kg,pickup,destination,status,idempotency_key,version,created_at,updated_at) VALUES('s1','c1','SMALL_PARCEL',1,'{}','{}','ARRIVED_AT_PICKUP','ship-k',1,?,?)").run(new Date().toISOString(),new Date().toISOString());orders.bindShipment({orderId:o.id,shipmentId:'s1'});db.prepare("UPDATE commerce_orders SET status='FULFILLMENT_REQUESTED' WHERE id=?").run(o.id);assert.throws(()=>orders.confirmCustody({orderId:o.id,to:'PICKED_UP'}),e=>e.code==='LOGISTICS_CUSTODY_NOT_CONFIRMED');db.prepare("UPDATE logistics_shipments SET status='PICKED_UP' WHERE id='s1'").run();assert.equal(orders.confirmCustody({orderId:o.id,to:'PICKED_UP'}).status,'PICKED_UP');db.prepare("UPDATE commerce_orders SET status='IN_TRANSIT' WHERE id=?").run(o.id);db.prepare("UPDATE logistics_shipments SET status='DELIVERED' WHERE id='s1'").run();assert.equal(orders.confirmCustody({orderId:o.id,to:'DELIVERED'}).status,'DELIVERED');db.close();});

test('merchant acceptance requires merchant actor and authoritative inventory reservation',()=>{const db=openStore(':memory:');const orders=createOrderAuthority({db}),inventory=createInventoryAuthority({db});const merchant={id:'m1',role:'agent'};const o=orders.create({customerId:'c1',merchantId:'m1',basket:[{sku:'x',qty:2}],total:200,currency:'KES',idempotencyKey:'merchant-bind'});db.prepare("UPDATE commerce_orders SET status='PAYMENT_CONFIRMED' WHERE id=?").run(o.id);inventory.setStock({merchantId:'m1',sku:'x',quantity:5,unitPrice:100,currency:'KES',actor:merchant});assert.throws(()=>orders.acceptByMerchant({orderId:o.id,actor:merchant}),e=>e.code==='ORDER_NOT_MERCHANT_PENDING');inventory.reserveForOrder({orderId:o.id,actor:merchant});db.prepare("UPDATE commerce_orders SET status='MERCHANT_PENDING' WHERE id=?").run(o.id);assert.throws(()=>orders.acceptByMerchant({orderId:o.id,actor:{id:'other',role:'agent'}}),e=>e.code==='MERCHANT_ACCEPTANCE_FORBIDDEN');assert.equal(orders.acceptByMerchant({orderId:o.id,actor:merchant}).status,'MERCHANT_ACCEPTED');assert.equal(db.prepare("SELECT quantity FROM commerce_inventory WHERE merchant_id='m1' AND sku='x'").get().quantity,3);db.close();});
test('inventory reservation is atomic on out of stock or changed price',()=>{const db=openStore(':memory:');const orders=createOrderAuthority({db}),inventory=createInventoryAuthority({db});const merchant={id:'m2',role:'agent'};const o=orders.create({customerId:'c1',merchantId:'m2',basket:[{sku:'a',qty:1},{sku:'b',qty:1}],total:200,currency:'KES',idempotencyKey:'stock-atomic'});db.prepare("UPDATE commerce_orders SET status='PAYMENT_CONFIRMED' WHERE id=?").run(o.id);inventory.setStock({merchantId:'m2',sku:'a',quantity:1,unitPrice:100,actor:merchant});inventory.setStock({merchantId:'m2',sku:'b',quantity:0,unitPrice:100,actor:merchant});assert.throws(()=>inventory.reserveForOrder({orderId:o.id,actor:merchant}),e=>e.code==='OUT_OF_STOCK');assert.equal(db.prepare("SELECT quantity FROM commerce_inventory WHERE merchant_id='m2' AND sku='a'").get().quantity,1);assert.equal(db.prepare("SELECT COUNT(*) AS n FROM commerce_inventory_reservations WHERE order_id=?").get(o.id).n,0);db.close();});

test('commerce REFUNDED is derived only from an authoritative verified refund',()=>{const db=openStore(':memory:');db.prepare("INSERT INTO users VALUES('admin','refund@x','Admin','x','admin',1)").run();const orders=createOrderAuthority({db}),payments=createPaymentAuthority({db}),admin={id:'admin',role:'admin'};const o=orders.create({customerId:'c1',merchantId:'m1',basket:[{sku:'x',qty:1}],total:100,currency:'KES',idempotencyKey:'refund-bind'});orders.transition({orderId:o.id,to:'VALIDATED'});makePayableCommerce({db,orders,order:o,unitPrice:o.total});const p=payments.createCommercePayment({orderId:o.id});payments.verifyCommerceManual({paymentId:p.id,reference:'PAYREF31',amount:100,actor:admin});db.prepare("UPDATE commerce_orders SET status='REFUND_PENDING' WHERE id=?").run(o.id);payments.markCommerceRefundPending({orderId:o.id,actor:admin});const r=payments.createCommerceRefund({orderId:o.id,actor:admin});assert.throws(()=>orders.confirmRefund({orderId:o.id,actor:admin}),e=>e.code==='COMMERCE_REFUND_NOT_CONFIRMED');assert.throws(()=>orders.transition({orderId:o.id,to:'REFUNDED',evidenceRef:'claimed'}),e=>e.code==='AUTHORITATIVE_BINDING_REQUIRED');payments.verifyCommerceRefundManual({refundId:r.id,reference:'REFUND31',amount:100,actor:admin});assert.equal(orders.confirmRefund({orderId:o.id,actor:admin}).status,'REFUNDED');assert.equal(orders.confirmRefund({orderId:o.id,actor:admin}).duplicate,true);db.close();});
test('refund authority rejects unauthorized, wrong amount, replay and double verification',()=>{const db=openStore(':memory:');db.prepare("INSERT INTO users VALUES('admin','refund2@x','Admin','x','admin',1)").run();const orders=createOrderAuthority({db}),payments=createPaymentAuthority({db}),admin={id:'admin',role:'admin'};const o=orders.create({customerId:'c1',merchantId:'m1',basket:[{sku:'x',qty:1}],total:250,currency:'KES',idempotencyKey:'refund-guards'});orders.transition({orderId:o.id,to:'VALIDATED'});makePayableCommerce({db,orders,order:o,unitPrice:o.total});const p=payments.createCommercePayment({orderId:o.id});payments.verifyCommerceManual({paymentId:p.id,reference:'PAYREF32',amount:250,actor:admin});db.prepare("UPDATE commerce_orders SET status='REFUND_PENDING' WHERE id=?").run(o.id);payments.markCommerceRefundPending({orderId:o.id,actor:admin});const r=payments.createCommerceRefund({orderId:o.id,actor:admin});assert.throws(()=>payments.verifyCommerceRefundManual({refundId:r.id,reference:'REFUND32',amount:250,actor:{id:'m1',role:'agent'}}),e=>e.code==='REFUND_VERIFICATION_FORBIDDEN');assert.throws(()=>payments.verifyCommerceRefundManual({refundId:r.id,reference:'REFUND32',amount:249,actor:admin}),e=>e.code==='AMOUNT_MISMATCH');assert.throws(()=>payments.verifyCommerceRefundManual({refundId:r.id,reference:'PAYREF32',amount:250,actor:admin}),e=>e.code==='REFERENCE_REPLAY');const done=payments.verifyCommerceRefundManual({refundId:r.id,reference:'REFUND32',amount:250,actor:admin});assert.equal(done.status,'refunded');assert.equal(payments.verifyCommerceRefundManual({refundId:r.id,reference:'REFUND32',amount:250,actor:admin}).duplicate,true);assert.throws(()=>payments.verifyCommerceRefundManual({refundId:r.id,reference:'OTHERREF32',amount:250,actor:admin}),e=>e.code==='REFUND_ALREADY_VERIFIED');db.close();});
test('refund amount boundary rejects coercible non-numeric input',()=>{const db=openStore(':memory:');const payments=createPaymentAuthority({db});assert.throws(()=>payments.verifyCommerceRefundManual({refundId:'missing',reference:'REFUND33',amount:'0',actor:{id:'admin',role:'admin'}}),e=>e.code==='INVALID_REFUND_AMOUNT');db.close();});

test('payment authority rejects coercible payment amounts and globally replays references',()=>{const db=openStore(':memory:');db.prepare("INSERT INTO users VALUES('admin','ledger@x','Admin','x','admin',1)").run();const orders=createOrderAuthority({db}),payments=createPaymentAuthority({db}),admin={id:'admin',role:'admin'};const o=orders.create({customerId:'c1',merchantId:'m1',basket:[{sku:'x',qty:1}],total:100,currency:'KES',idempotencyKey:'ledger-pay'});orders.transition({orderId:o.id,to:'VALIDATED'});makePayableCommerce({db,orders,order:o,unitPrice:o.total});const p=payments.createCommercePayment({orderId:o.id});assert.throws(()=>payments.verifyCommerceManual({paymentId:p.id,reference:'LEDGER01',amount:'100',actor:admin}),e=>e.code==='INVALID_PAYMENT_AMOUNT');payments.verifyCommerceManual({paymentId:p.id,reference:'LEDGER01',amount:100,actor:admin});assert.equal(db.prepare("SELECT kind FROM payment_references WHERE reference='LEDGER01'").get().kind,'commerce_payment');db.prepare("UPDATE commerce_orders SET status='REFUND_PENDING' WHERE id=?").run(o.id);payments.markCommerceRefundPending({orderId:o.id,actor:admin});const r=payments.createCommerceRefund({orderId:o.id,actor:admin});assert.throws(()=>payments.verifyCommerceRefundManual({refundId:r.id,reference:'LEDGER01',amount:100,actor:admin}),e=>e.code==='REFERENCE_REPLAY');db.close();});

test('verified commerce payment creates immutable credit ledger event and reconciliation',()=>{const db=openStore(':memory:');db.prepare("INSERT INTO users VALUES('admin','recon@x','Admin','x','admin',1)").run();const ledger=createLedgerAuthority({db}),payments=createPaymentAuthority({db,ledger}),orders=createOrderAuthority({db}),admin={id:'admin',role:'admin'};const o=orders.create({customerId:'c1',merchantId:'m1',basket:[{sku:'x',qty:1}],total:300,currency:'KES',idempotencyKey:'recon-pay'});orders.transition({orderId:o.id,to:'VALIDATED'});makePayableCommerce({db,orders,order:o,unitPrice:o.total});const p=payments.createCommercePayment({orderId:o.id});payments.verifyCommerceManual({paymentId:p.id,reference:'RECONPAY1',amount:300,actor:admin});const e=db.prepare("SELECT * FROM financial_ledger_events WHERE kind='commerce_payment' AND entity_id=?").get(p.id);assert.equal(e.direction,'CREDIT');assert.equal(e.amount,300);assert.equal(db.prepare('SELECT status FROM reconciliation_records WHERE ledger_event_id=?').get(e.id).status,'PENDING');const matched=ledger.reconcile({ledgerEventId:e.id,observedAmount:300,evidenceRef:'statement:1',actor:admin});assert.equal(matched.status,'MATCHED');assert.equal(matched.discrepancy,0);assert.equal(ledger.reconcile({ledgerEventId:e.id,observedAmount:300,evidenceRef:'statement:1',actor:admin}).duplicate,true);db.close();});
test('reconciliation detects discrepancy and immutable ledger rejects conflicting duplicate',()=>{const db=openStore(':memory:');db.prepare("INSERT INTO users VALUES('admin','recon2@x','Admin','x','admin',1)").run();const ledger=createLedgerAuthority({db}),admin={id:'admin',role:'admin'};const e=ledger.record({eventType:'PAYMENT_CAPTURED',kind:'test_payment',entityId:'p1',reference:'REF1',amount:500,currency:'KES',direction:'CREDIT',provider:'manual',actor:admin});assert.equal(ledger.record({eventType:'PAYMENT_CAPTURED',kind:'test_payment',entityId:'p1',reference:'REF1',amount:500,currency:'KES',direction:'CREDIT',provider:'manual',actor:admin}).duplicate,true);assert.throws(()=>ledger.record({eventType:'PAYMENT_CAPTURED',kind:'test_payment',entityId:'p1',reference:'REF1',amount:501,currency:'KES',direction:'CREDIT',provider:'manual',actor:admin}),e=>e.code==='LEDGER_EVENT_CONFLICT');assert.throws(()=>ledger.reconcile({ledgerEventId:e.id,observedAmount:450,evidenceRef:'statement:2',actor:{id:'m1',role:'agent'}}),e=>e.code==='RECONCILIATION_FORBIDDEN');const r=ledger.reconcile({ledgerEventId:e.id,observedAmount:450,evidenceRef:'statement:2',actor:admin});assert.equal(r.status,'DISCREPANCY');assert.equal(r.discrepancy,-50);db.close();});

test('authenticated provider callback confirms commerce payment and is replay safe',()=>{const {createHmac}=require('node:crypto');const db=openStore(':memory:');const ledger=createLedgerAuthority({db}),payments=createPaymentAuthority({db,ledger}),orders=createOrderAuthority({db});const o=orders.create({customerId:'c1',merchantId:'m1',basket:[{sku:'x',qty:1}],total:420,currency:'KES',idempotencyKey:'provider-pay'});orders.transition({orderId:o.id,to:'VALIDATED'});makePayableCommerce({db,orders,order:o,unitPrice:o.total});const p=payments.createCommercePayment({orderId:o.id});const secret='test-only-secret',boundary=createProviderBoundary({db,paymentAuthority:payments,providers:{mpesa:createMpesaAdapter({webhookSecret:secret})}});const intents=createPaymentIntentAuthority({db,providers:{mpesa:createMpesaAdapter({webhookSecret:secret,initiate:req=>({providerRequestId:'legacy-'+req.correlationId})})}});const intent=intents.create({paymentKind:'commerce_payment',paymentId:p.id,provider:'mpesa',customerContact:'254700000000',idempotencyKey:'legacy-provider-1'});const raw=JSON.stringify({eventId:'evt-1',correlationId:intent.correlation_id,paymentKind:'commerce_payment',paymentId:p.id,type:'PAYMENT_SUCCEEDED',reference:'MPESA420',amount:420,currency:'KES'}),sig=createHmac('sha256',secret).update(raw).digest('hex');const done=boundary.handle({provider:'mpesa',rawBody:raw,signature:sig});assert.equal(done.status,'paid');assert.equal(db.prepare("SELECT provider FROM financial_ledger_events WHERE entity_id=?").get(p.id).provider,'mpesa');const duplicate=boundary.handle({provider:'mpesa',rawBody:raw,signature:sig});assert.equal(duplicate.duplicate,true);db.close();});
test('provider boundary rejects unsigned, mismatched and conflicting replay callbacks',()=>{const {createHmac}=require('node:crypto');const db=openStore(':memory:');const payments=createPaymentAuthority({db}),orders=createOrderAuthority({db});const o=orders.create({customerId:'c1',merchantId:'m1',basket:[{sku:'x',qty:1}],total:500,currency:'KES',idempotencyKey:'provider-guards'});orders.transition({orderId:o.id,to:'VALIDATED'});makePayableCommerce({db,orders,order:o,unitPrice:500});const p=payments.createCommercePayment({orderId:o.id}),secret='test-only-secret',boundary=createProviderBoundary({db,paymentAuthority:payments,providers:{mpesa:createMpesaAdapter({webhookSecret:secret})}});const intents=createPaymentIntentAuthority({db,providers:{mpesa:createMpesaAdapter({webhookSecret:secret,initiate:req=>({providerRequestId:'legacy2-'+req.correlationId})})}});const intent=intents.create({paymentKind:'commerce_payment',paymentId:p.id,provider:'mpesa',customerContact:'254700000002',idempotencyKey:'legacy-provider-2'});const body=x=>JSON.stringify({eventId:'evt-2',correlationId:intent.correlation_id,paymentKind:'commerce_payment',paymentId:p.id,type:'PAYMENT_SUCCEEDED',reference:'MPESA500',amount:x,currency:'KES'});assert.throws(()=>boundary.receive({provider:'mpesa',rawBody:body(500),signature:'bad'}),e=>e.code==='INVALID_PROVIDER_SIGNATURE');let raw=body(499),sig=createHmac('sha256',secret).update(raw).digest('hex');assert.throws(()=>boundary.handle({provider:'mpesa',rawBody:raw,signature:sig}),e=>e.code==='PROVIDER_INTENT_AMOUNT_MISMATCH');raw=body(500);sig=createHmac('sha256',secret).update(raw).digest('hex');boundary.handle({provider:'mpesa',rawBody:raw,signature:sig});const altered=JSON.stringify({...JSON.parse(raw),amount:501});const alteredSig=createHmac('sha256',secret).update(altered).digest('hex');assert.throws(()=>boundary.receive({provider:'mpesa',rawBody:altered,signature:alteredSig}),e=>e.code==='PROVIDER_INTENT_AMOUNT_MISMATCH');db.close();});

test('payment intent initiates provider request idempotently and callback must bind to intent',()=>{const {createHmac}=require('node:crypto');const db=openStore(':memory:');const ledger=createLedgerAuthority({db}),payments=createPaymentAuthority({db,ledger}),orders=createOrderAuthority({db}),secret='intent-secret';let calls=0;const mpesa=createMpesaAdapter({webhookSecret:secret,initiate:req=>{calls++;return {providerRequestId:'stk-'+req.correlationId}}});const intents=createPaymentIntentAuthority({db,providers:{mpesa}}),boundary=createProviderBoundary({db,paymentAuthority:payments,providers:{mpesa}});const o=orders.create({customerId:'c1',merchantId:'m1',basket:[{sku:'x',qty:1}],total:700,currency:'KES',idempotencyKey:'intent-order'});orders.transition({orderId:o.id,to:'VALIDATED'});makePayableCommerce({db,orders,order:o,unitPrice:o.total});const p=payments.createCommercePayment({orderId:o.id});const draft=intents.create({paymentKind:'commerce_payment',paymentId:p.id,provider:'mpesa',customerContact:'254700000001',idempotencyKey:'intent-1'});assert.equal(draft.status,'PENDING_INITIATION');assert.equal(calls,0);assert.equal(intents.create({paymentKind:'commerce_payment',paymentId:p.id,provider:'mpesa',customerContact:'254700000001',idempotencyKey:'intent-1'}).duplicate,true);const i=intents.process({intentId:draft.id});assert.equal(i.status,'REQUESTED');assert.equal(calls,1);const raw=JSON.stringify({eventId:'intent-evt',correlationId:i.correlation_id,paymentKind:'commerce_payment',paymentId:p.id,type:'PAYMENT_SUCCEEDED',reference:'MPESA700',amount:700,currency:'KES'}),sig=createHmac('sha256',secret).update(raw).digest('hex');assert.equal(boundary.handle({provider:'mpesa',rawBody:raw,signature:sig}).status,'paid');assert.equal(db.prepare('SELECT status FROM payment_intents WHERE id=?').get(i.id).status,'CONFIRMED');db.close();});
test('provider callback cannot confirm payment without matching intent',()=>{const {createHmac}=require('node:crypto');const db=openStore(':memory:');const payments=createPaymentAuthority({db}),orders=createOrderAuthority({db}),secret='intent-secret';const mpesa=createMpesaAdapter({webhookSecret:secret,initiate:()=>({providerRequestId:'unused'})}),boundary=createProviderBoundary({db,paymentAuthority:payments,providers:{mpesa}});const o=orders.create({customerId:'c1',merchantId:'m1',basket:[{sku:'x',qty:1}],total:800,currency:'KES',idempotencyKey:'intent-guard'});orders.transition({orderId:o.id,to:'VALIDATED'});makePayableCommerce({db,orders,order:o,unitPrice:o.total});const p=payments.createCommercePayment({orderId:o.id});const raw=JSON.stringify({eventId:'orphan-evt',correlationId:'not-an-intent',paymentKind:'commerce_payment',paymentId:p.id,type:'PAYMENT_SUCCEEDED',reference:'MPESA800',amount:800,currency:'KES'}),sig=createHmac('sha256',secret).update(raw).digest('hex');assert.throws(()=>boundary.handle({provider:'mpesa',rawBody:raw,signature:sig}),e=>e.code==='PROVIDER_CORRELATION_MISMATCH');assert.equal(db.prepare('SELECT status FROM commerce_payments WHERE id=?').get(p.id).status,'pending');db.close();});

test('provider settlement automatically reconciles matching immutable ledger event',()=>{const db=openStore(':memory:');db.prepare("INSERT INTO users VALUES('admin','settle@x','Admin','x','admin',1)").run();const ledger=createLedgerAuthority({db}),admin={id:'admin',role:'admin'},e=ledger.record({eventType:'PAYMENT_CAPTURED',kind:'commerce_payment',entityId:'settle-p1',reference:'MPESA900',amount:900,currency:'KES',direction:'CREDIT',provider:'mpesa',actor:admin}),settlements=createSettlementAuthority({db,ledger});const x=settlements.ingest({provider:'mpesa',providerSettlementId:'batch-1:line-1',reference:'MPESA900',amount:900,currency:'KES',settledAt:'2026-10-01T09:00:00.000Z',evidenceRef:'statement:batch-1:line-1',rawPayload:'immutable-line-1',actor:admin});assert.equal(x.reconciliation_status,'MATCHED');assert.equal(x.ledger_event_id,e.id);const r=db.prepare('SELECT * FROM reconciliation_records WHERE ledger_event_id=?').get(e.id);assert.equal(r.status,'MATCHED');assert.equal(r.observed_amount,900);assert.equal(settlements.ingest({provider:'mpesa',providerSettlementId:'batch-1:line-1',reference:'MPESA900',amount:900,currency:'KES',settledAt:'2026-10-01T09:00:00.000Z',evidenceRef:'statement:batch-1:line-1',rawPayload:'immutable-line-1',actor:admin}).duplicate,true);db.close();});
test('provider settlement records discrepancy and rejects conflicting replay',()=>{const db=openStore(':memory:');db.prepare("INSERT INTO users VALUES('admin','settle2@x','Admin','x','admin',1)").run();const ledger=createLedgerAuthority({db}),admin={id:'admin',role:'admin'},e=ledger.record({eventType:'PAYMENT_CAPTURED',kind:'commerce_payment',entityId:'settle-p2',reference:'MPESA1000',amount:1000,currency:'KES',direction:'CREDIT',provider:'mpesa',actor:admin}),settlements=createSettlementAuthority({db,ledger}),args={provider:'mpesa',providerSettlementId:'batch-2:line-1',reference:'MPESA1000',amount:950,currency:'KES',settledAt:'2026-10-01T10:00:00.000Z',evidenceRef:'statement:batch-2:line-1',rawPayload:'immutable-line-2',actor:admin};assert.equal(settlements.ingest(args).reconciliation_status,'DISCREPANCY');const r=db.prepare('SELECT * FROM reconciliation_records WHERE ledger_event_id=?').get(e.id);assert.equal(r.status,'DISCREPANCY');assert.equal(r.discrepancy,-50);assert.throws(()=>settlements.ingest({...args,amount:951}),e=>e.code==='SETTLEMENT_REPLAY_CONFLICT');assert.throws(()=>settlements.ingest({...args,providerSettlementId:'batch-2:line-2',actor:{id:'m1',role:'agent'}}),e=>e.code==='SETTLEMENT_INGEST_FORBIDDEN');db.close();});
test('unmatched provider settlement remains evidence without fabricating a ledger match',()=>{const db=openStore(':memory:');db.prepare("INSERT INTO users VALUES('admin','settle3@x','Admin','x','admin',1)").run();const settlements=createSettlementAuthority({db,ledger:createLedgerAuthority({db})}),x=settlements.ingest({provider:'mpesa',providerSettlementId:'batch-3:line-1',reference:'UNKNOWN900',amount:900,currency:'KES',settledAt:'2026-10-01T11:00:00.000Z',evidenceRef:'statement:batch-3:line-1',rawPayload:'immutable-line-3',actor:{id:'admin',role:'admin'}});assert.equal(x.reconciliation_status,'UNMATCHED');assert.equal(x.ledger_event_id,null);db.close();});

test('commerce cancellation preflight prevents side effects for non-cancellable order',()=>{const db=openStore(':memory:');db.prepare("INSERT INTO users VALUES('admin','cancel@x','Admin','x','admin',1)").run();const orders=createOrderAuthority({db}),inventory=createInventoryAuthority({db}),payments=createPaymentAuthority({db}),admin={id:'admin',role:'admin'},o=orders.create({customerId:'c1',merchantId:'m1',basket:[{sku:'x',qty:1}],total:100,currency:'KES',idempotencyKey:'cancel-preflight'});db.prepare("UPDATE commerce_orders SET status='DELIVERED' WHERE id=?").run(o.id);db.prepare("INSERT INTO commerce_inventory(merchant_id,sku,quantity,unit_price,currency,version,updated_at) VALUES('m1','x',4,100,'KES',1,?)").run(new Date().toISOString());db.prepare("INSERT INTO commerce_inventory_reservations(id,order_id,merchant_id,sku,quantity,status,created_at) VALUES('r-cancel',?,'m1','x',1,'RESERVED',?)").run(o.id,new Date().toISOString());const coordinator=createCommerceCancellationCoordinator({db,inventoryAuthority:inventory,paymentAuthority:payments,orderAuthority:orders});assert.throws(()=>coordinator.start({orderId:o.id,actor:admin}),e=>e.code==='ORDER_NOT_CANCELLABLE');assert.equal(db.prepare("SELECT status FROM commerce_inventory_reservations WHERE id='r-cancel'").get().status,'RESERVED');assert.equal(db.prepare("SELECT quantity FROM commerce_inventory WHERE merchant_id='m1' AND sku='x'").get().quantity,4);db.close();});
test('commerce cancellation finalizes through Order Authority and records evidence event',()=>{const db=openStore(':memory:');db.prepare("INSERT INTO users VALUES('admin','cancel2@x','Admin','x','admin',1)").run();const orders=createOrderAuthority({db}),inventory=createInventoryAuthority({db}),payments=createPaymentAuthority({db}),admin={id:'admin',role:'admin'},o=orders.create({customerId:'c1',merchantId:'m1',basket:[{sku:'x',qty:1}],total:100,currency:'KES',idempotencyKey:'cancel-authority'});const coordinator=createCommerceCancellationCoordinator({db,inventoryAuthority:inventory,paymentAuthority:payments,orderAuthority:orders});const done=coordinator.start({orderId:o.id,actor:admin});assert.equal(done.status,'COMPLETED');assert.equal(orders.get(o.id).status,'CANCELLED');const event=db.prepare("SELECT * FROM commerce_order_events WHERE order_id=? AND event_type='CANCELLED'").get(o.id);assert.ok(event);assert.match(event.evidence_ref,/^cancellation-operation:/);assert.equal(coordinator.start({orderId:o.id,actor:admin}).duplicate,true);db.close();});
test('commerce recovery mutations require admin authority',()=>{const db=openStore(':memory:');const orders=createOrderAuthority({db}),inventory=createInventoryAuthority({db}),payments=createPaymentAuthority({db}),o=orders.create({customerId:'c1',merchantId:'m1',basket:[{sku:'x',qty:1}],total:100,currency:'KES',idempotencyKey:'cancel-rbac'});orders.transition({orderId:o.id,to:'VALIDATED'});makePayableCommerce({db,orders,order:o,unitPrice:100});payments.createCommercePayment({orderId:o.id});assert.throws(()=>payments.cancelCommercePending({orderId:o.id,actor:{id:'m1',role:'agent'}}),e=>e.code==='PAYMENT_RECOVERY_FORBIDDEN');assert.throws(()=>inventory.releaseForOrder({orderId:o.id,actor:{id:'other',role:'agent'}}),e=>e.code==='MERCHANT_INVENTORY_FORBIDDEN');db.close();});

test('commerce money boundaries reject coercible string values',()=>{const db=openStore(':memory:');const orders=createOrderAuthority({db}),inventory=createInventoryAuthority({db});assert.throws(()=>orders.create({customerId:'c1',merchantId:'m1',basket:[{sku:'x',qty:1}],total:'100',currency:'KES',idempotencyKey:'money-string'}),e=>e.code==='INVALID_TOTAL');assert.throws(()=>inventory.setStock({merchantId:'m1',sku:'x',quantity:'2',unitPrice:100,actor:{id:'m1',role:'agent'}}),e=>e.code==='INVALID_INVENTORY');assert.throws(()=>inventory.setStock({merchantId:'m1',sku:'x',quantity:2,unitPrice:'100',actor:{id:'m1',role:'agent'}}),e=>e.code==='INVALID_INVENTORY');db.close();});
test('pricing authority derives total from authoritative inventory and emits bound price event',()=>{const db=openStore(':memory:');const orders=createOrderAuthority({db}),inventory=createInventoryAuthority({db}),pricing=createPricingAuthority({db}),merchant={id:'m1',role:'agent'};inventory.setStock({merchantId:'m1',sku:'x',quantity:5,unitPrice:125,currency:'KES',actor:merchant});const o=orders.create({customerId:'c1',merchantId:'m1',basket:[{sku:'x',qty:2}],total:250,currency:'KES',idempotencyKey:'price-authority'});orders.transition({orderId:o.id,to:'VALIDATED',actor:merchant});assert.throws(()=>orders.transition({orderId:o.id,to:'PRICE_CONFIRMED',evidenceRef:'caller-claim',actor:merchant}),e=>e.code==='AUTHORITATIVE_BINDING_REQUIRED');const p=pricing.confirm({orderId:o.id,actor:merchant});assert.equal(p.amount,250);assert.equal(orders.get(o.id).status,'PRICE_CONFIRMED');const event=db.prepare("SELECT * FROM commerce_order_events WHERE order_id=? AND event_type='PRICE_CONFIRMED'").get(o.id);assert.equal(event.evidence_ref,'price-confirmation:'+p.id);assert.equal(pricing.confirm({orderId:o.id,actor:merchant}).duplicate,true);db.close();});
test('pricing authority rejects caller total that differs from inventory-derived amount',()=>{const db=openStore(':memory:');const orders=createOrderAuthority({db}),inventory=createInventoryAuthority({db}),pricing=createPricingAuthority({db}),merchant={id:'m1',role:'agent'};inventory.setStock({merchantId:'m1',sku:'x',quantity:2,unitPrice:100,currency:'KES',actor:merchant});const o=orders.create({customerId:'c1',merchantId:'m1',basket:[{sku:'x',qty:2}],total:199,currency:'KES',idempotencyKey:'price-mismatch'});orders.transition({orderId:o.id,to:'VALIDATED',actor:merchant});assert.throws(()=>pricing.confirm({orderId:o.id,actor:merchant}),e=>e.code==='ORDER_TOTAL_MISMATCH');assert.equal(orders.get(o.id).status,'VALIDATED');db.close();});

test('payment intent is durable before provider initiation and processing is resumable',()=>{const db=openStore(':memory:');const orders=createOrderAuthority({db}),payments=createPaymentAuthority({db});const o=orders.create({customerId:'c1',merchantId:'m1',basket:[{sku:'x',qty:1}],total:175,currency:'KES',idempotencyKey:'outbox-order'});orders.transition({orderId:o.id,to:'VALIDATED'});makePayableCommerce({db,orders,order:o,unitPrice:o.total});const p=payments.createCommercePayment({orderId:o.id});let calls=0;const intents=createPaymentIntentAuthority({db,providers:{mpesa:{initiatePayment:req=>{calls++;return {providerRequestId:'REQ-'+req.correlationId};}}}});const draft=intents.create({paymentKind:'commerce_payment',paymentId:p.id,provider:'mpesa',customerContact:'254700000000',idempotencyKey:'outbox-intent'});assert.equal(draft.status,'PENDING_INITIATION');assert.equal(calls,0);const out=db.prepare('SELECT * FROM payment_initiation_outbox WHERE payment_intent_id=?').get(draft.id);assert.equal(out.status,'PENDING');const sent=intents.process({intentId:draft.id});assert.equal(sent.status,'REQUESTED');assert.equal(calls,1);assert.equal(intents.process({intentId:draft.id}).duplicate,true);assert.equal(calls,1);assert.equal(db.prepare('SELECT status FROM payment_initiation_outbox WHERE payment_intent_id=?').get(draft.id).status,'SENT');db.close();});
test('failed provider initiation preserves durable intent and retryable outbox',()=>{const db=openStore(':memory:');const orders=createOrderAuthority({db}),payments=createPaymentAuthority({db});const o=orders.create({customerId:'c1',merchantId:'m1',basket:[{sku:'x',qty:1}],total:90,currency:'KES',idempotencyKey:'outbox-fail-order'});orders.transition({orderId:o.id,to:'VALIDATED'});makePayableCommerce({db,orders,order:o,unitPrice:o.total});const p=payments.createCommercePayment({orderId:o.id});let fail=true,now=new Date('2026-10-01T09:00:00.000Z');const intents=createPaymentIntentAuthority({db,clock:()=>now,baseBackoffMs:1000,providers:{mpesa:{initiatePayment:req=>{if(fail)throw Object.assign(new Error('provider down'),{code:'PROVIDER_DOWN'});return {providerRequestId:'REQ-'+req.correlationId};}}}});const draft=intents.create({paymentKind:'commerce_payment',paymentId:p.id,provider:'mpesa',customerContact:'254700000001',idempotencyKey:'outbox-fail-intent'});assert.throws(()=>intents.process({intentId:draft.id}),e=>e.code==='PROVIDER_DOWN');assert.equal(intents.get(draft.id).status,'PENDING_INITIATION');let out=db.prepare('SELECT * FROM payment_initiation_outbox WHERE payment_intent_id=?').get(draft.id);assert.equal(out.status,'FAILED');assert.equal(out.attempts,1);assert.equal(out.next_attempt_at,'2026-10-01T09:00:01.000Z');fail=false;now=new Date('2026-10-01T09:00:01.000Z');const sent=intents.process({intentId:draft.id});assert.equal(sent.status,'REQUESTED');out=db.prepare('SELECT * FROM payment_initiation_outbox WHERE payment_intent_id=?').get(draft.id);assert.equal(out.status,'SENT');assert.equal(out.attempts,2);db.close();});

test('authenticated callback is durably received before payment mutation and can be processed later',()=>{const {createHmac}=require('node:crypto');const db=openStore(':memory:');const payments=createPaymentAuthority({db}),orders=createOrderAuthority({db}),secret='inbox-secret';const o=orders.create({customerId:'c1',merchantId:'m1',basket:[{sku:'x',qty:1}],total:610,currency:'KES',idempotencyKey:'inbox-order'});orders.transition({orderId:o.id,to:'VALIDATED'});makePayableCommerce({db,orders,order:o,unitPrice:610});const p=payments.createCommercePayment({orderId:o.id}),mpesa=createMpesaAdapter({webhookSecret:secret,initiate:req=>({providerRequestId:'inbox-'+req.correlationId})}),intents=createPaymentIntentAuthority({db,providers:{mpesa}}),boundary=createProviderBoundary({db,paymentAuthority:payments,providers:{mpesa}});const draft=intents.create({paymentKind:'commerce_payment',paymentId:p.id,provider:'mpesa',customerContact:'254700000010',idempotencyKey:'inbox-intent'}),intent=intents.process({intentId:draft.id});const raw=JSON.stringify({eventId:'inbox-evt',correlationId:intent.correlation_id,paymentKind:'commerce_payment',paymentId:p.id,type:'PAYMENT_SUCCEEDED',reference:'MPESA610',amount:610,currency:'KES'}),sig=createHmac('sha256',secret).update(raw).digest('hex');const inbox=boundary.receive({provider:'mpesa',rawBody:raw,signature:sig});assert.equal(inbox.status,'RECEIVED');assert.equal(db.prepare('SELECT status FROM commerce_payments WHERE id=?').get(p.id).status,'pending');const done=boundary.process({inboxId:inbox.id});assert.equal(done.status,'paid');assert.equal(db.prepare('SELECT status FROM provider_callback_inbox WHERE id=?').get(inbox.id).status,'PROCESSED');assert.equal(db.prepare('SELECT status FROM payment_intents WHERE id=?').get(intent.id).status,'CONFIRMED');db.close();});

test('callback receive duplicate resolves idempotently inside atomic receive transaction',()=>{const {createHmac}=require('node:crypto');const db=openStore(':memory:'),payments=createPaymentAuthority({db}),orders=createOrderAuthority({db}),secret='receive-idempotency-secret';const o=orders.create({customerId:'c1',merchantId:'m1',basket:[{sku:'x',qty:1}],total:615,currency:'KES',idempotencyKey:'receive-idempotency-order'});orders.transition({orderId:o.id,to:'VALIDATED'});makePayableCommerce({db,orders,order:o,unitPrice:615});const p=payments.createCommercePayment({orderId:o.id}),mpesa=createMpesaAdapter({webhookSecret:secret,initiate:req=>({providerRequestId:'receive-idem-'+req.correlationId})}),intents=createPaymentIntentAuthority({db,providers:{mpesa}}),boundary=createProviderBoundary({db,paymentAuthority:payments,providers:{mpesa}}),intent=intents.process({intentId:intents.create({paymentKind:'commerce_payment',paymentId:p.id,provider:'mpesa',customerContact:'254700000046',idempotencyKey:'receive-idempotency-intent'}).id}),raw=JSON.stringify({eventId:'receive-idempotency-evt',correlationId:intent.correlation_id,paymentKind:'commerce_payment',paymentId:p.id,type:'PAYMENT_SUCCEEDED',reference:'MPESA615',amount:615,currency:'KES'}),sig=createHmac('sha256',secret).update(raw).digest('hex'),first=boundary.receive({provider:'mpesa',rawBody:raw,signature:sig}),second=boundary.receive({provider:'mpesa',rawBody:raw,signature:sig});assert.equal(second.id,first.id);assert.equal(second.duplicate,true);assert.equal(db.prepare('SELECT COUNT(*) n FROM provider_callback_inbox WHERE provider_event_id=?').get('receive-idempotency-evt').n,1);assert.equal(db.prepare('SELECT status FROM commerce_payments WHERE id=?').get(p.id).status,'pending');db.close();});

test('callback receive rejects same provider event id with conflicting authenticated payload',()=>{const {createHmac}=require('node:crypto');const db=openStore(':memory:'),payments=createPaymentAuthority({db}),orders=createOrderAuthority({db}),secret='receive-conflict-secret';const o=orders.create({customerId:'c1',merchantId:'m1',basket:[{sku:'x',qty:1}],total:616,currency:'KES',idempotencyKey:'receive-conflict-order'});orders.transition({orderId:o.id,to:'VALIDATED'});makePayableCommerce({db,orders,order:o,unitPrice:616});const p=payments.createCommercePayment({orderId:o.id}),mpesa=createMpesaAdapter({webhookSecret:secret,initiate:req=>({providerRequestId:'receive-conflict-'+req.correlationId})}),intents=createPaymentIntentAuthority({db,providers:{mpesa}}),boundary=createProviderBoundary({db,paymentAuthority:payments,providers:{mpesa}}),intent=intents.process({intentId:intents.create({paymentKind:'commerce_payment',paymentId:p.id,provider:'mpesa',customerContact:'254700000047',idempotencyKey:'receive-conflict-intent'}).id}),event={eventId:'receive-conflict-evt',correlationId:intent.correlation_id,paymentKind:'commerce_payment',paymentId:p.id,type:'PAYMENT_SUCCEEDED',reference:'MPESA616',amount:616,currency:'KES'},raw=JSON.stringify(event),sig=createHmac('sha256',secret).update(raw).digest('hex');boundary.receive({provider:'mpesa',rawBody:raw,signature:sig});const altered=JSON.stringify({...event,reference:'MPESA616ALTERED'}),alteredSig=createHmac('sha256',secret).update(altered).digest('hex');assert.throws(()=>boundary.receive({provider:'mpesa',rawBody:altered,signature:alteredSig}),e=>e.code==='PROVIDER_EVENT_REPLAY_CONFLICT');assert.equal(db.prepare('SELECT COUNT(*) n FROM provider_callback_inbox WHERE provider_event_id=?').get(event.eventId).n,1);assert.equal(db.prepare('SELECT reference FROM provider_callback_inbox WHERE provider_event_id=?').get(event.eventId).reference,'MPESA616');db.close();});

test('callback processing failure is durable and retryable',()=>{const {createHmac}=require('node:crypto');const db=openStore(':memory:');const real=createPaymentAuthority({db}),orders=createOrderAuthority({db}),secret='inbox-retry-secret';const o=orders.create({customerId:'c1',merchantId:'m1',basket:[{sku:'x',qty:1}],total:620,currency:'KES',idempotencyKey:'inbox-retry-order'});orders.transition({orderId:o.id,to:'VALIDATED'});makePayableCommerce({db,orders,order:o,unitPrice:620});const p=real.createCommercePayment({orderId:o.id}),mpesa=createMpesaAdapter({webhookSecret:secret,initiate:req=>({providerRequestId:'retry-'+req.correlationId})}),intents=createPaymentIntentAuthority({db,providers:{mpesa}}),draft=intents.create({paymentKind:'commerce_payment',paymentId:p.id,provider:'mpesa',customerContact:'254700000011',idempotencyKey:'inbox-retry-intent'}),intent=intents.process({intentId:draft.id});let fail=true;const wrapped={verifyCommerceProviderInsideTransaction:x=>{if(fail)throw Object.assign(new Error('temporary'),{code:'TEMPORARY_AUTHORITY_FAILURE'});return real.verifyCommerceProviderInsideTransaction(x);},verifyBookingProviderInsideTransaction:x=>real.verifyBookingProviderInsideTransaction(x)},boundary=createProviderBoundary({db,paymentAuthority:wrapped,providers:{mpesa}});const raw=JSON.stringify({eventId:'inbox-retry-evt',correlationId:intent.correlation_id,paymentKind:'commerce_payment',paymentId:p.id,type:'PAYMENT_SUCCEEDED',reference:'MPESA620',amount:620,currency:'KES'}),sig=createHmac('sha256',secret).update(raw).digest('hex'),inbox=boundary.receive({provider:'mpesa',rawBody:raw,signature:sig});assert.throws(()=>boundary.process({inboxId:inbox.id}),e=>e.code==='TEMPORARY_AUTHORITY_FAILURE');let row=db.prepare('SELECT * FROM provider_callback_inbox WHERE id=?').get(inbox.id);assert.equal(row.status,'FAILED');assert.equal(row.attempts,1);fail=false;assert.equal(boundary.process({inboxId:inbox.id}).status,'paid');row=db.prepare('SELECT * FROM provider_callback_inbox WHERE id=?').get(inbox.id);assert.equal(row.status,'PROCESSED');assert.equal(row.attempts,2);db.close();});


test('callback atomicity rolls back payment mutation when provider-event persistence fails',()=>{const {createHmac}=require('node:crypto');const db=openStore(':memory:');const payments=createPaymentAuthority({db}),orders=createOrderAuthority({db}),secret='atomic-event-secret';const o=orders.create({customerId:'c1',merchantId:'m1',basket:[{sku:'x',qty:1}],total:630,currency:'KES',idempotencyKey:'atomic-event-order'});orders.transition({orderId:o.id,to:'VALIDATED'});makePayableCommerce({db,orders,order:o,unitPrice:630});const p=payments.createCommercePayment({orderId:o.id}),mpesa=createMpesaAdapter({webhookSecret:secret,initiate:req=>({providerRequestId:'atomic-event-'+req.correlationId})}),intents=createPaymentIntentAuthority({db,providers:{mpesa}}),boundary=createProviderBoundary({db,paymentAuthority:payments,providers:{mpesa}});const intent=intents.process({intentId:intents.create({paymentKind:'commerce_payment',paymentId:p.id,provider:'mpesa',customerContact:'254700000040',idempotencyKey:'atomic-event-intent'}).id});const raw=JSON.stringify({eventId:'atomic-event-evt',correlationId:intent.correlation_id,paymentKind:'commerce_payment',paymentId:p.id,type:'PAYMENT_SUCCEEDED',reference:'MPESA630',amount:630,currency:'KES'}),sig=createHmac('sha256',secret).update(raw).digest('hex'),inbox=boundary.receive({provider:'mpesa',rawBody:raw,signature:sig});db.exec("CREATE TRIGGER fail_provider_event_insert BEFORE INSERT ON provider_payment_events BEGIN SELECT RAISE(ABORT,'FAIL_PROVIDER_EVENT_INSERT'); END");assert.throws(()=>boundary.process({inboxId:inbox.id}));assert.equal(db.prepare('SELECT status FROM commerce_payments WHERE id=?').get(p.id).status,'pending');assert.equal(db.prepare('SELECT COUNT(*) AS n FROM payment_references WHERE reference=?').get('MPESA630').n,0);assert.equal(db.prepare('SELECT status FROM payment_intents WHERE id=?').get(intent.id).status,'REQUESTED');const failed=db.prepare('SELECT * FROM provider_callback_inbox WHERE id=?').get(inbox.id);assert.equal(failed.status,'FAILED');assert.equal(failed.attempts,1);db.exec('DROP TRIGGER fail_provider_event_insert');assert.equal(boundary.process({inboxId:inbox.id}).status,'paid');assert.equal(db.prepare('SELECT status FROM payment_intents WHERE id=?').get(intent.id).status,'CONFIRMED');db.close();});

