test('app payment provider runtime stays manual without configured provider and enables injected provider',async()=>{const manual=createApp({dbPath:':memory:',startSideEffectRuntime:false});assert.ok(manual.paymentIntentAuthority);assert.ok(manual.providerBoundary);assert.ok(manual.paymentAuthority);await manual.close();const provider={initiatePayment:()=>({providerRequestId:'configured'}),lookupPayment:()=>null,verifySignature:()=>true,parseEvent:()=>null};const configured=createApp({dbPath:':memory:',startSideEffectRuntime:false,paymentProviders:{test:provider}});assert.ok(configured.paymentIntentAuthority);assert.ok(configured.providerBoundary);await configured.close();});



test('provider callback runtime drains bounded recovery backlog and stops cleanly',()=>{let calls=0,cleared=false;const boundary={processDue:({limit})=>{calls++;assert.equal(limit,3);return [{ok:true}]}};const runtime=createProviderCallbackRuntime({boundary,batchSize:3,setIntervalFn:()=>({unref(){}}),clearIntervalFn:()=>{cleared=true;}});runtime.start();assert.equal(calls,1);runtime.stop();assert.equal(cleared,true);assert.deepEqual(runtime.drain(),[]);});

test('provider callback processDue recovers received and expired processing rows',()=>{const db=openStore(':memory:');const now=new Date().toISOString(),past=new Date(Date.now()-60000).toISOString();for(const [id,status,lease] of [['r','RECEIVED',null],['x','PROCESSING',past]])db.prepare("INSERT INTO provider_callback_inbox(id,provider,provider_event_id,correlation_id,payment_kind,payment_id,event_type,reference,amount,currency,payload_hash,normalized_event,status,attempts,received_at,updated_at,lease_owner,lease_expires_at) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)").run(id,'test','evt-'+id,'corr-'+id,'commerce_payment','pay-'+id,'PAYMENT_SUCCEEDED','ref-'+id,1,'KES','hash-'+id,'{}',status,0,now,now,lease?'old-worker':null,lease);const seen=[];const authority={verifyCommerceProviderInsideTransaction:()=>{throw Object.assign(new Error('EXPECTED_TEST_STOP'),{code:'EXPECTED_TEST_STOP'})},verifyBookingProviderInsideTransaction:()=>{}};const boundary=createProviderBoundary({db,paymentAuthority:authority,providers:{}});const results=boundary.processDue({workerId:'recovery',limit:10});assert.equal(results.length,2);assert.equal(results.every(x=>x.ok===false),true);assert.deepEqual(results.map(x=>x.inboxId).sort(),['r','x']);assert.equal(db.prepare("SELECT status FROM provider_callback_inbox WHERE id='r'").get().status,'FAILED');assert.equal(db.prepare("SELECT status,lease_owner FROM provider_callback_inbox WHERE id='x'").get().status,'FAILED');assert.equal(db.prepare("SELECT lease_owner FROM provider_callback_inbox WHERE id='x'").get().lease_owner,null);db.close();});

test('payment initiation runtime drains bounded due work and isolates provider failures',()=>{let calls=0;const authority={processNext:()=>{calls++;if(calls===1)throw Object.assign(new Error('PROVIDER_DOWN'),{code:'PROVIDER_DOWN'});if(calls===2)return {id:'recovered'};return null;}};const runtime=createPaymentInitiationRuntime({authority,batchSize:5,setIntervalFn:()=>({unref(){}}),clearIntervalFn:()=>{}});runtime.start();assert.equal(calls,3);assert.equal(runtime.running,false);runtime.stop();});

test('payment initiation runtime prevents overlapping drains and stops cleanly',()=>{let scheduled,cleared=false,calls=0;const authority={processNext:()=>{calls++;return null;}};const runtime=createPaymentInitiationRuntime({authority,setIntervalFn:fn=>{scheduled=fn;return {unref(){}};},clearIntervalFn:()=>{cleared=true;}});runtime.start();assert.equal(calls,1);scheduled();assert.equal(calls,2);runtime.stop();assert.equal(cleared,true);assert.deepEqual(runtime.drain(),[]);});

test('side-effect runtime drains startup backlog and stops cleanly',()=>{const db=openStore(':memory:');let delivered=0,scheduled=null,cleared=false;const outbox=createPaymentSideEffectOutbox({db,handlers:{TEST_EFFECT:()=>{delivered++;}}});db.exec('BEGIN IMMEDIATE');outbox.enqueueInsideTransaction({eventKey:'runtime-startup-1',effectType:'TEST_EFFECT',payload:{}});db.exec('COMMIT');const runtime=createSideEffectRuntime({outbox,workerId:'runtime-worker',setIntervalFn:fn=>{scheduled=fn;return {unref(){}};},clearIntervalFn:()=>{cleared=true;}});runtime.start();assert.equal(delivered,1);assert.equal(db.prepare("SELECT status FROM payment_side_effect_outbox WHERE event_key='runtime-startup-1'").get().status,'DELIVERED');assert.equal(typeof scheduled,'function');runtime.stop();assert.equal(cleared,true);db.close();});

test('side-effect runtime does not overlap drains',()=>{let calls=0,reenter;const outbox={processDue:()=>{calls++;if(reenter)reenter();return [];}};const runtime=createSideEffectRuntime({outbox,workerId:'runtime-no-overlap',setIntervalFn:()=>({unref(){}}),clearIntervalFn:()=>{}});reenter=()=>runtime.drain();runtime.start();assert.equal(calls,1);runtime.stop();});

test('commerce payment creation requires authoritative price confirmation',()=>{const db=openStore(':memory:');const orders=createOrderAuthority({db}),payments=createPaymentAuthority({db});const o=orders.create({customerId:'c1',merchantId:'m1',basket:[{sku:'x',qty:1}],total:100,currency:'KES',idempotencyKey:'price-bind-required'});orders.transition({orderId:o.id,to:'VALIDATED'});db.prepare("UPDATE commerce_orders SET status='PAYMENT_PENDING' WHERE id=?").run(o.id);assert.throws(()=>payments.createCommercePayment({orderId:o.id}),e=>e.code==='PRICE_CONFIRMATION_REQUIRED');assert.equal(db.prepare('SELECT COUNT(*) AS n FROM commerce_payments WHERE order_id=?').get(o.id).n,0);db.close();});
test('commerce payment rejects stale inventory version after price confirmation',()=>{const db=openStore(':memory:');const orders=createOrderAuthority({db}),payments=createPaymentAuthority({db}),inventory=createInventoryAuthority({db});const o=orders.create({customerId:'c1',merchantId:'m1',basket:[{sku:'x',qty:1}],total:100,currency:'KES',idempotencyKey:'price-bind-stale'});orders.transition({orderId:o.id,to:'VALIDATED'});const {merchant}=makePayableCommerce({db,orders,order:o,unitPrice:100});inventory.setStock({merchantId:'m1',sku:'x',quantity:5,unitPrice:101,currency:'KES',actor:merchant});assert.throws(()=>payments.createCommercePayment({orderId:o.id}),e=>e.code==='PRICE_CONFIRMATION_STALE');assert.equal(db.prepare('SELECT COUNT(*) AS n FROM commerce_payments WHERE order_id=?').get(o.id).n,0);db.close();});

test('repricing preserves historical confirmation and requires customer acknowledgement before payment',()=>{const db=openStore(':memory:');const orders=createOrderAuthority({db}),inventory=createInventoryAuthority({db}),pricing=createPricingAuthority({db}),payments=createPaymentAuthority({db}),merchant={id:'m1',role:'agent'};const o=orders.create({customerId:'c1',merchantId:'m1',basket:[{sku:'x',qty:2}],total:200,currency:'KES',idempotencyKey:'reprice-1'});orders.transition({orderId:o.id,to:'VALIDATED'});inventory.setStock({merchantId:'m1',sku:'x',quantity:5,unitPrice:100,currency:'KES',actor:merchant});const first=pricing.confirm({orderId:o.id,actor:merchant});orders.transition({orderId:o.id,to:'PAYMENT_PENDING'});inventory.setStock({merchantId:'m1',sku:'x',quantity:5,unitPrice:125,currency:'KES',actor:merchant});assert.throws(()=>payments.createCommercePayment({orderId:o.id}),e=>e.code==='PRICE_CONFIRMATION_STALE');const second=pricing.reprice({orderId:o.id,actor:merchant});assert.equal(second.amount,250);assert.equal(second.supersedes_id,first.id);assert.equal(db.prepare('SELECT status FROM commerce_price_confirmations WHERE id=?').get(first.id).status,'SUPERSEDED');assert.equal(db.prepare('SELECT total FROM commerce_orders WHERE id=?').get(o.id).total,250);orders.transition({orderId:o.id,to:'PAYMENT_PENDING'});assert.throws(()=>payments.createCommercePayment({orderId:o.id}),e=>e.code==='PRICE_ACKNOWLEDGEMENT_REQUIRED');pricing.acknowledge({orderId:o.id,customerId:'c1'});const p=payments.createCommercePayment({orderId:o.id});assert.equal(p.amount,250);assert.equal(db.prepare('SELECT COUNT(*) AS n FROM commerce_price_confirmations WHERE order_id=?').get(o.id).n,2);db.close();});
test('repricing cannot replace evidence after payment exists and acknowledgement is customer-bound',()=>{const db=openStore(':memory:');const orders=createOrderAuthority({db}),inventory=createInventoryAuthority({db}),pricing=createPricingAuthority({db}),payments=createPaymentAuthority({db}),merchant={id:'m1',role:'agent'};const o=orders.create({customerId:'c1',merchantId:'m1',basket:[{sku:'x',qty:1}],total:100,currency:'KES',idempotencyKey:'reprice-guards'});orders.transition({orderId:o.id,to:'VALIDATED'});inventory.setStock({merchantId:'m1',sku:'x',quantity:5,unitPrice:100,currency:'KES',actor:merchant});pricing.confirm({orderId:o.id,actor:merchant});orders.transition({orderId:o.id,to:'PAYMENT_PENDING'});const p=payments.createCommercePayment({orderId:o.id});assert.ok(p.id);inventory.setStock({merchantId:'m1',sku:'x',quantity:5,unitPrice:110,currency:'KES',actor:merchant});assert.throws(()=>pricing.reprice({orderId:o.id,actor:merchant}),e=>e.code==='PAYMENT_ALREADY_EXISTS');assert.throws(()=>pricing.acknowledge({orderId:o.id,customerId:'other'}),e=>e.code==='PRICE_ACKNOWLEDGEMENT_FORBIDDEN');db.close();});

test('payment outbox worker claims once and competing worker cannot process active lease',()=>{const db=openStore(':memory:');const orders=createOrderAuthority({db}),payments=createPaymentAuthority({db});const o=orders.create({customerId:'c1',merchantId:'m1',basket:[{sku:'x',qty:1}],total:330,currency:'KES',idempotencyKey:'worker-lease'});orders.transition({orderId:o.id,to:'VALIDATED'});makePayableCommerce({db,orders,order:o,unitPrice:330});const p=payments.createCommercePayment({orderId:o.id});let calls=0;const intents=createPaymentIntentAuthority({db,providers:{mpesa:{initiatePayment:()=>{calls++;return {providerRequestId:'lease-1'}}}}});const i=intents.create({paymentKind:'commerce_payment',paymentId:p.id,provider:'mpesa',customerContact:'254700000020',idempotencyKey:'worker-lease-i'});const claimed=intents.claim({intentId:i.id,workerId:'w1'});assert.equal(claimed.status,'PROCESSING');assert.throws(()=>intents.claim({intentId:i.id,workerId:'w2'}),e=>e.code==='OUTBOX_ALREADY_LEASED');assert.equal(calls,0);db.close();});
test('payment outbox failure schedules exponential retry and eventually dead letters',()=>{const db=openStore(':memory:');const orders=createOrderAuthority({db}),payments=createPaymentAuthority({db});const o=orders.create({customerId:'c1',merchantId:'m1',basket:[{sku:'x',qty:1}],total:340,currency:'KES',idempotencyKey:'worker-retry'});orders.transition({orderId:o.id,to:'VALIDATED'});makePayableCommerce({db,orders,order:o,unitPrice:340});const p=payments.createCommercePayment({orderId:o.id});let now=new Date('2026-10-01T10:00:00.000Z'),calls=0;const intents=createPaymentIntentAuthority({db,clock:()=>now,maxAttempts:2,baseBackoffMs:1000,providers:{mpesa:{initiatePayment:()=>{calls++;throw Object.assign(new Error('down'),{code:'PROVIDER_DOWN'});}}}});const i=intents.create({paymentKind:'commerce_payment',paymentId:p.id,provider:'mpesa',customerContact:'254700000021',idempotencyKey:'worker-retry-i'});assert.throws(()=>intents.process({intentId:i.id,workerId:'w1'}),e=>e.code==='PROVIDER_DOWN');let out=db.prepare('SELECT * FROM payment_initiation_outbox WHERE payment_intent_id=?').get(i.id);assert.equal(out.status,'FAILED');assert.equal(out.attempts,1);assert.equal(out.next_attempt_at,'2026-10-01T10:00:01.000Z');assert.throws(()=>intents.process({intentId:i.id,workerId:'w2'}),e=>e.code==='OUTBOX_NOT_DUE');now=new Date('2026-10-01T10:00:01.000Z');assert.throws(()=>intents.process({intentId:i.id,workerId:'w2'}),e=>e.code==='PROVIDER_DOWN');out=db.prepare('SELECT * FROM payment_initiation_outbox WHERE payment_intent_id=?').get(i.id);assert.equal(out.status,'DEAD_LETTER');assert.equal(out.attempts,2);assert.equal(out.next_attempt_at,null);assert.equal(calls,2);db.close();});
test('expired payment outbox lease is recoverable by another worker',()=>{const db=openStore(':memory:');const orders=createOrderAuthority({db}),payments=createPaymentAuthority({db});const o=orders.create({customerId:'c1',merchantId:'m1',basket:[{sku:'x',qty:1}],total:350,currency:'KES',idempotencyKey:'worker-recover'});orders.transition({orderId:o.id,to:'VALIDATED'});makePayableCommerce({db,orders,order:o,unitPrice:350});const p=payments.createCommercePayment({orderId:o.id});let now=new Date('2026-10-01T11:00:00.000Z');const intents=createPaymentIntentAuthority({db,clock:()=>now,leaseMs:1000,providers:{mpesa:{initiatePayment:()=>({providerRequestId:'recovered'})}}});const i=intents.create({paymentKind:'commerce_payment',paymentId:p.id,provider:'mpesa',customerContact:'254700000022',idempotencyKey:'worker-recover-i'});intents.claim({intentId:i.id,workerId:'crashed'});now=new Date('2026-10-01T11:00:02.000Z');const claimed=intents.claim({intentId:i.id,workerId:'recovery'});assert.equal(claimed.lease_owner,'recovery');assert.equal(claimed.status,'PROCESSING');db.close();});

test('provider initiation uses stable correlation id as provider idempotency key',()=>{const db=openStore(':memory:');const orders=createOrderAuthority({db}),payments=createPaymentAuthority({db});const o=orders.create({customerId:'c1',merchantId:'m1',basket:[{sku:'x',qty:1}],total:360,currency:'KES',idempotencyKey:'provider-idem-order'});orders.transition({orderId:o.id,to:'VALIDATED'});makePayableCommerce({db,orders,order:o,unitPrice:360});const p=payments.createCommercePayment({orderId:o.id});let seen;const adapter=createMpesaAdapter({initiate:req=>{seen=req;return {providerRequestId:'provider-idem-1'}}});const intents=createPaymentIntentAuthority({db,providers:{mpesa:adapter}});const i=intents.create({paymentKind:'commerce_payment',paymentId:p.id,provider:'mpesa',customerContact:'254700000030',idempotencyKey:'provider-idem-intent'});intents.process({intentId:i.id});assert.equal(seen.idempotencyKey,i.correlation_id);assert.equal(seen.correlationId,i.correlation_id);const out=db.prepare('SELECT * FROM payment_initiation_outbox WHERE payment_intent_id=?').get(i.id);assert.equal(out.status,'SENT');assert.ok(out.provider_acknowledgement);assert.ok(out.provider_acknowledged_at);db.close();});
test('provider acceptance recovery closes crash window without duplicate initiation',()=>{const db=openStore(':memory:');const orders=createOrderAuthority({db}),payments=createPaymentAuthority({db});const o=orders.create({customerId:'c1',merchantId:'m1',basket:[{sku:'x',qty:1}],total:370,currency:'KES',idempotencyKey:'provider-recover-order'});orders.transition({orderId:o.id,to:'VALIDATED'});makePayableCommerce({db,orders,order:o,unitPrice:370});const p=payments.createCommercePayment({orderId:o.id});let initiateCalls=0,lookupCalls=0,accepted=false,providerRequestId;const adapter=createMpesaAdapter({initiate:req=>{initiateCalls++;accepted=true;providerRequestId='accepted-'+req.correlationId;throw Object.assign(new Error('simulated crash after provider acceptance'),{code:'TRANSPORT_LOST_AFTER_ACCEPT'});},lookup:({correlationId})=>{lookupCalls++;return accepted?{providerRequestId,correlationId}:null;}});let now=new Date('2026-10-01T12:00:00.000Z');const intents=createPaymentIntentAuthority({db,clock:()=>now,baseBackoffMs:1000,providers:{mpesa:adapter}});const i=intents.create({paymentKind:'commerce_payment',paymentId:p.id,provider:'mpesa',customerContact:'254700000031',idempotencyKey:'provider-recover-intent'});assert.throws(()=>intents.process({intentId:i.id,workerId:'w1'}),e=>e.code==='TRANSPORT_LOST_AFTER_ACCEPT');assert.equal(initiateCalls,1);now=new Date('2026-10-01T12:00:01.000Z');const recovered=intents.process({intentId:i.id,workerId:'w2'});assert.equal(recovered.status,'REQUESTED');assert.equal(recovered.provider_request_id,providerRequestId);assert.equal(initiateCalls,1);assert.ok(lookupCalls>=1);const out=db.prepare('SELECT * FROM payment_initiation_outbox WHERE payment_intent_id=?').get(i.id);assert.equal(out.status,'SENT');const evidence=JSON.parse(out.provider_acknowledgement);assert.equal(evidence.recovered,true);assert.equal(evidence.providerRequestId,providerRequestId);db.close();});
test('provider recovery rejects correlation mismatch evidence',()=>{const db=openStore(':memory:');const orders=createOrderAuthority({db}),payments=createPaymentAuthority({db});const o=orders.create({customerId:'c1',merchantId:'m1',basket:[{sku:'x',qty:1}],total:380,currency:'KES',idempotencyKey:'provider-mismatch-order'});orders.transition({orderId:o.id,to:'VALIDATED'});makePayableCommerce({db,orders,order:o,unitPrice:380});const p=payments.createCommercePayment({orderId:o.id});const adapter=createMpesaAdapter({initiate:()=>({providerRequestId:'unused'}),lookup:()=>({providerRequestId:'wrong',correlationId:'different'})});const intents=createPaymentIntentAuthority({db,providers:{mpesa:adapter}});const i=intents.create({paymentKind:'commerce_payment',paymentId:p.id,provider:'mpesa',customerContact:'254700000032',idempotencyKey:'provider-mismatch-intent'});assert.throws(()=>intents.recoverProviderAcceptance({intentId:i.id}),e=>e.code==='PROVIDER_CORRELATION_MISMATCH');assert.equal(intents.get(i.id).status,'PENDING_INITIATION');db.close();});
